import { PrizeLeagueManager } from './services/prize-league/prize-league-manager';

export abstract class Bootstrap {
    private static skinInitialiser: Promise<void> | null = null;
    private static skinLoader: Promise<void> | null = null;
    /** amounts of the loading bar dedicated to each section */
    private static readonly loadPercent = {
        cabinet: 0.05,
        core: 0.25,
        skin: 0.45,
        gamePreload: 0.15,
        /** for when canLazyLoad is false */
        nonlazy: 0.1
    };
    private static currentLoadProgress: number = 0;

    public static initAuth(): Promise<void> {
        return container.frameConnection.operator.onInit({
            gameName: queryStringParams.currentSkin,
            locale: getLocaleString(),
            version: gameConfig.version
        });
    }

    /**
     * Initialises the required bindings allowing for a skin to be loaded.
     * Can be called multiple times but will only run once.
     * @returns A promise that resolves when the skin has been initialised.
     */
    public static initialiseSkin(): Promise<void> {
        if (this.skinInitialiser !== null) {
            return this.skinInitialiser;
        }

        this.skinInitialiser = new Promise<void>(async (resolve) => {
            await featureToggles.load();
            await this.buildInjectedFactories();
            // TODO: This probably needs to be an injectable based on the operator
            // arcade-gig-config.json and bingo-gig-config.json only exist for tombola
            // normally for any 3rd party operators it is "gig-config.json"
            const isLaunchedFromArcade = queryStringParams.launchedFrom === 'arcade';
            const locale = getLocaleString();
            const gigFileName = (locale === 'en-GB') ? isLaunchedFromArcade ? 'arcade-gig-config.json' : 'bingo-gig-config.json' : 'gig-config.json';

            await inversifyContainer.get<IGameInGameManager>(Injects.GameInGameManager).fetchGames(gigFileName);

            if (isLaunchedFromArcade && gameConfig.features.enablePrizeLeague) { //Remove arcade check to enable on core site
                await inversifyContainer.get<PrizeLeagueManager>(Injects.PrizeLeagueManager).init();
            }

            gameConfig.assetQuality = inversifyContainer.get<() => string>(Injects.AssetQualityGetter)();
            await this.initialiseFonts();
            resolve();
        });

        return this.skinInitialiser;
    }

    /**
     * Loads the skin assets.
     * @returns A promise that resolves when the skin assets have been loaded.
     */
    public static loadSkin(): Promise<void> {
        if (this.skinLoader !== null) {
            return this.skinLoader;
        }

        this.skinLoader = new Promise<void>(async (resolve) => {
            await this.loadAssets();
            loggingModel.recordAssetChunkEndTime();

            endGameValidator.reset();
            await this.initialiseUserPrefs();
            resolve();
        });

        return this.skinLoader;
    }

    /**
     * Runs the bootstrap process to load the skin and game assets.
     * Calls initialiseSkin and loadSkin up front.
     */
    public static async run(): Promise<void> {
        try {
            // Check if we should enter unauthenticated demo mode - set flag before resume
            demoState.isUnauthenticatedDemo = queryStringParams.isUnAuthDemoMode;

            await this.initialiseSkin();
            await this.loadSkin();

            if (inversifyContainer.isBound(Injects.PreloadAssetsFunction)) {
                loggingModel.recordAssetChunkStartTime();
                await inversifyContainer.get<(callback: (progress: number) => void) => void>(Injects.PreloadAssetsFunction).call(this, (progress: number) => {
                    this.updateLoadBar(progress, this.loadPercent.gamePreload);
                });
                loggingModel.recordAssetChunkEndTime();
                this.currentLoadProgress += this.loadPercent.gamePreload;
            }

            if (inversifyContainer.gameModel.canLazyLoad === false) {
                await Bootstrap.loadLazyAssets(this.currentLoadProgress, this.loadPercent.nonlazy);
                BaseGame.isLazyLoadComplete = true;
            }
            this.updateLoadBar(1, this.loadPercent.nonlazy);
            this.currentLoadProgress += this.loadPercent.nonlazy;

            if (!gameConfig.ignoreResumeData) {
                await this.handleResumeData();
            }

            await this.localiseDynamicStrings();
            eventEmitter.emit('GLOBAL_LOADING_COMPLETE');
        } catch (error) {
            if (error instanceof Error) {
                const errorMessage = `Bootstrap Error: ${error.message}`;
                console.error(errorMessage);
            }
            bootstrapErrorModel.error = true;
        }
    }

    public static async loadLazyAssets(preProgress?: number, additionalProgress?: number): Promise<Record<string, any>> {
        const usingLocalAssets: boolean = gameConfig.features.usingLocalAssets;

        if (usingLocalAssets) {
            const localSkinLazyAssetList: IAssetConfig | undefined = inversifyContainer.skin.lazyAssetList;

            if (localSkinLazyAssetList === undefined) { return Promise.resolve({}); }

            return this.loadAssetConfig(localSkinLazyAssetList, '', preProgress, additionalProgress);
        } else {
            if (!AssetManager.hasAsset('lazy-asset-list')) {
                return Promise.resolve({});
            }

            return this.loadAssetConfig(AssetManager.getJsonData<IAssetConfig>('lazy-asset-list'), inversifyContainer.adminSettings.assetVersion.skin, preProgress, additionalProgress);
        }
    }

    private static updateLoadBar(progress: number, segmentSize: number): void {
        const changeInProgress = progress * segmentSize;
        const newProgress = this.currentLoadProgress + changeInProgress;
        eventEmitter.emit('GLOBAL_LOADING_PROGRESS', newProgress);
    }

    private static useLocalAssets(): void {
        inversifyContainer.endPoints.urls[environment].cdnRoot = `http://127.0.0.1:${process.env.LOCALASSETPORT}/`;
        Object.assign(inversifyContainer.adminSettings, {
            sharedStrings: '',
            errorStrings: '',
            settingsStrings: '',
            assetVersion: {
                core: '',
                skin: ''
            }
        });

        // eslint-disable-next-line no-console
        console.log(`Using local assets on ${inversifyContainer.endPoints.urls[environment].cdnRoot}`);
    }

    private static async buildInjectedFactories(): Promise<void> {
        // TODO: Investigate turning all these individual factory injections into a single delayedInjector function for clearer intent
        // An Issue being they generally need to happen in a specific order - so difficult to break up when some are defined by the game and some the engine
        try {
            // await inversifyContainer.get<() => HostRequestAdapter | void>(Injects.ApiClientFactory).call(this);
            await inversifyContainer.get<() => ISkinDesc>(Injects.SkinFactory).call(this);
            await inversifyContainer.get<() => IAdminSettings>(Injects.AdminSettingsFactory).call(this);
            if (environment === 'debug' && process.env.LOCALASSETPORT !== void (0)) {
                this.useLocalAssets();
            }
            await inversifyContainer.get<() => IStrings>(Injects.StringsFactory).call(this);
            await inversifyContainer.get<() => IGameServer>(Injects.GameServerFactory).call(this);
            await inversifyContainer.get<() => BaseCabinet>(Injects.ComponentsFactory).call(this);
            if (inversifyContainer.isBound(Injects.ChatRulesOverrideFactory)) {
                await inversifyContainer.get<() => VueConstructor<Vue>>(Injects.ChatRulesOverrideFactory).call(this);
            }
        } catch (error) {
            console.error('Binding Factory Error: Specifics below');
            if (error instanceof Error && error.toString().includes('strings.json')) {
                console.error(error.toString() + '\n\nIf not intending to load strings from the cdn ensure you are binding to Injects.Strings in your bindings file.');
            } else { console.error(error); }
        }
    }

    private static loadDataList(data: IAssetConfig, version: string): Promise<Record<string, any>> {
        data.version = version;
        data.baseUrl = inversifyContainer.endPoints.urls[environment].cdnRoot + inversifyContainer.endPoints.urls[environment].cdnGameName;
        return AssetManager.load(data);
    }

    private static async loadAssets(): Promise<void> {
        const usingLocalAssets: boolean = gameConfig.features.usingLocalAssets;

        let coreAssetList: IAssetConfig;
        let skinAssetList: IAssetConfig;
        let skinAssetConfigs: AssetConfigs;

        let coreAssetVersion: string = '';
        let skinAssetVersion: string = '';

        if (usingLocalAssets) {
            coreAssetList = Bootstrap.overrideRegionalAssets(inversifyContainer.localDataList, 'core').assetConfig;
            skinAssetConfigs = Bootstrap.overrideRegionalAssets(inversifyContainer.skin.dataList as AssetData, gameConfig.assetFolder);
            skinAssetList = skinAssetConfigs.assetConfig;

            const skinData: ISkinDesc = {
                dataList: skinAssetList,
                config: inversifyContainer.skin.config,
                lazyAssetList: skinAssetConfigs.lazyAssetConfig
            };

            inversifyContainer.rebind<ISkinDesc>(Injects.Skin).toConstantValue(skinData);
        } else {
            const coreDataList = (inversifyContainer.coreDataList).assetList.data;
            const skinDataList = (inversifyContainer.skin.dataList as IBaseDataList).assetList.data;

            if (coreDataList === undefined || coreDataList[0] === undefined) {
                throw new Error('Missing Data from Core Data List while NOT using Local Assets. Please check your Core Data List or ENABLE `usingLocalAssets` in features.');
            }

            if (skinDataList === undefined || skinDataList[0] === undefined) {
                throw new Error('Missing Data from Skin Data List while NOT using Local Assets. Please check your Skin Data List or ENABLE `usingLocalAssets` in features.');
            }

            await this.loadDataList(inversifyContainer.coreDataList as IAssetConfig, inversifyContainer.adminSettings.assetVersion.core);
            await this.loadDataList(inversifyContainer.skin.dataList as IAssetConfig, inversifyContainer.adminSettings.assetVersion.skin);

            const coreAssetListName = coreDataList[0].name;
            const skinAssetListName = skinDataList[0].name;

            coreAssetList = AssetManager.getJsonData<IAssetConfig>(coreAssetListName);
            skinAssetList = AssetManager.getJsonData<IAssetConfig>(skinAssetListName);

            coreAssetVersion = inversifyContainer.adminSettings.assetVersion.core;
            skinAssetVersion = inversifyContainer.adminSettings.assetVersion.skin;
        }

        const cabinetBaseUrl = './static/assets/';
        await inversifyContainer.cabinet.loadAssets(cabinetBaseUrl, (progress: number) => { this.updateLoadBar(progress, this.loadPercent.cabinet); });
        this.currentLoadProgress += this.loadPercent.cabinet;

        await this.loadAssetConfig(coreAssetList, coreAssetVersion, this.currentLoadProgress, this.loadPercent.core);
        this.currentLoadProgress += this.loadPercent.core;
        await this.loadAssetConfig(skinAssetList, skinAssetVersion, this.currentLoadProgress, this.loadPercent.skin);
        this.currentLoadProgress += this.loadPercent.skin;
    }

    private static loadAssetConfig(assetConfig: IAssetConfig, version: string, preProgress?: number, additionalProgress?: number): Promise<Record<string, any>> {
        const cdnGameName = inversifyContainer.endPoints.urls[environment].cdnGameName;
        const cdnBaseUrl: string = inversifyContainer.endPoints.urls[environment].cdnRoot + cdnGameName;
        const localUrl: string = './static/assets/';

        assetConfig.version = version;

        if (gameConfig.features.usingLocalAssets) {
            assetConfig.baseUrl = localUrl;
        } else {
            assetConfig.baseUrl = cdnBaseUrl;
        }

        const deviceDependantAssets = (assetConfig as ICdnAssetConfig).deviceDependantAssets;

        if (deviceDependantAssets !== undefined) {
            if (device.type.isDesktop) {
                assetConfig.assetList = merge(assetConfig.assetList, deviceDependantAssets.desktop);
            } else {
                assetConfig.assetList = merge(assetConfig.assetList, deviceDependantAssets.mobile);
            }
        }

        // TODO: update all game asset-lists to have url instead of skeleton
        this.convertLegacyAssetConfigs(assetConfig);

        // Replace all instances of {ogg,mp3} with mp3 in IE and Edge
        if ((device.info.browser.name === 'IE') || (device.info.browser.name === 'Edge')) {
            if (assetConfig.assetList.sounds) {
                for (const item of assetConfig.assetList.sounds) {
                    const legacyAsset = item as ILegacySoundAssetConfig;
                    if (legacyAsset.url !== undefined) {
                        legacyAsset.url = legacyAsset.url.replace('{ogg,mp3}', 'mp3');
                    } else {
                        const howlSoundAsset = item as IHowlSoundAssetConfig;
                        if (Array.isArray(howlSoundAsset.src)) {
                            howlSoundAsset.src = howlSoundAsset.src.map((src) => src.replace('{ogg,mp3}', 'mp3'));
                        } else {
                            howlSoundAsset.src = howlSoundAsset.src.replace('{ogg,mp3}', 'mp3');
                        }
                    }
                }
            }
        }

        const fixDependencies = (checkItem: IBaseAssetConfig) => {
            checkItem.url = checkItem.url.replace('{quality}', gameConfig.assetQuality);
            if (checkItem.dependencies) {
                checkItem.dependencies.forEach((subItem: IBaseAssetConfig) => {
                    fixDependencies(subItem);
                });
            }
        };

        // Replace all {quality} tags with the desired quality to match the folder on cdn
        for (const list of Object.values(assetConfig.assetList)) {
            for (const item of list) {
                if (item.url) {
                    // most assets hold the url in the url parameter
                    item.url = item.url.replace('{quality}', gameConfig.assetQuality);
                } else if (item.skeleton) {
                    // animations hold the url in the skeleton parameter
                    item.skeleton = item.skeleton.replace('{quality}', gameConfig.assetQuality);
                }

                if (item.options?.metadata?.spineAtlasFile) {
                    // some assets provide a separate atlas filepath
                    item.options.metadata.spineAtlasFile = item.options.metadata.spineAtlasFile.replace('{quality}', gameConfig.assetQuality);
                }

                fixDependencies(item);
            }
        }

        return AssetManager.load(assetConfig, (progress) => {
            if (preProgress !== undefined && additionalProgress !== undefined) {
                this.updateLoadBar(preProgress, (progress * additionalProgress));
            }
        });
    }

    // TODO: Remove this function once all games are switched to the new format
    private static convertLegacyAssetConfigs(assetConfig: IAssetConfig): void {
        // haCk: workaround for the interface change in the game-studio/asset-manager
        // Allows us to update the games slowly over time without immediate asset changes required
        interface ILegacyAnimationAssetConfig {
            name: string;
            texture?: string;
            textures?: { [key: string]: string; };
            atlas?: string;
            skeleton: string;
        }

        function isLegacyAsset(item: ILegacyAnimationAssetConfig | IAnimationAssetConfig): item is ILegacyAnimationAssetConfig {
            return (item as ILegacyAnimationAssetConfig).skeleton !== undefined;
        }

        if (assetConfig.assetList.animations) {
            for (const item of assetConfig.assetList.animations) {
                if (isLegacyAsset(item)) {
                    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                    // @ts-ignore
                    item['url'] = item['skeleton']; delete item['skeleton'];
                }
            }
        }
        // eNd oF HAck___________
    }

    private static overrideRegionalAssets(skinDataList: AssetData, skinName: string): AssetConfigs {
        const assetConfig: IAssetConfig = {
            baseUrl: '',
            assetList: {},
            skin: skinName,
            version: ''
        };

        const lazyAssetConfig: IAssetConfig = JSON.parse(JSON.stringify(assetConfig));
        const currentRegion: Locale = queryStringParams.locale;
        const assetRegions: AssetRegion[] = currentRegion !== 'en-gb' ? ['international', currentRegion] : [currentRegion];

        let hasLazyAssets: boolean = false;

        for (const key in skinDataList.default) {
            const typedKey = key as keyof IAssetList;

            if (typedKey === 'webFonts') { continue; }

            const assetType = skinDataList.default[typedKey] as IBaseAssetConfig[];

            if (assetType === undefined) { continue; }

            assetType.forEach(assetData => {
                let assetListEntry = assetConfig.assetList[typedKey] as IBaseAssetConfig[];
                let lazyAssetEntry = lazyAssetConfig.assetList[typedKey] as IBaseAssetConfig[];

                if (assetListEntry === undefined) { assetListEntry = []; }
                if (lazyAssetEntry === undefined) { lazyAssetEntry = []; }

                const correctAssetList: IBaseAssetConfig[] = assetData.isLazyLoad ? lazyAssetEntry : assetListEntry;

                if (assetData.isLazyLoad) { hasLazyAssets = true; }

                let newAssetEntry = assetData;

                for (let i = assetRegions.length - 1; i >= 0; i--) {
                    const region = assetRegions[i];
                    const regionalOverrides = skinDataList[region];

                    if (regionalOverrides) {
                        const regionalOverride = regionalOverrides[typedKey];

                        if (regionalOverride) {
                            const assetEntry = regionalOverride.find((assetEntry) => { return assetEntry.name === assetData.name; });

                            if (assetEntry !== undefined) {
                                newAssetEntry = assetEntry;
                                break;
                            }
                        }
                    }
                }

                // removes the isLazyLoad flag as we've already handled that
                // and don't want the asset manager to do it's native lazy load approach
                newAssetEntry.isLazyLoad = undefined;

                correctAssetList.push(newAssetEntry);

                (assetConfig.assetList[typedKey] as IBaseAssetConfig[]) = assetListEntry;
                (lazyAssetConfig.assetList[typedKey] as IBaseAssetConfig[]) = lazyAssetEntry;
            });
        }

        if (hasLazyAssets) {
            return { assetConfig: assetConfig, lazyAssetConfig: lazyAssetConfig };
        }

        return { assetConfig: assetConfig, lazyAssetConfig: undefined };
    }

    private static initialiseFonts(): Promise<void> {
        const sharedFontsCSSFilePath = './static/fonts/shared/sharedFonts-v1.css';
        return new Promise<void>((resolve, reject) => {
            WebFont.load({
                custom: {
                    families: ['Lato-Regular', 'Lato-Lig', 'Lato-Bold', 'Wallop-Bold', 'Wallop', ...inversifyContainer.skin.config.fonts],
                    urls: [sharedFontsCSSFilePath, gameConfig.fontCSSFilepath]
                },
                active: resolve,
                inactive: reject
            });
        }).catch(() => {
            const message = `Error loading ${gameConfig.fontCSSFilepath}. Ensure this is the correct path for your fonts css file.\nPath can be defined in config.json, defaults to './static/fonts/fonts-v2.css' if not defined.`;
            console.error(message);
        });
    }

    private static async initialiseUserPrefs(): Promise<void> {
        UserPreferences.init(userModel.userId, queryStringParams.currentSkin);
        if (queryStringParams.isSubGame === true) {
            userPreferences.update({ music: false });
            userPreferences.update({ sound: false });
        }
        await userPreferences.initShellPreferences();
    }

    public static handleResumeData(resumeData?: IBaseServerResponse): Promise<void> {
        if (resumeData) {
            this.setResumeData(resumeData);
            return Promise.resolve();
        } else {
            return this.sendResumeRequest()
                .then((response) => {
                    this.setResumeData(response);
                    return;
                })
                .catch((response) => {
                    let errorMessage = 'Resume Request Error';
                    const resultCode = response.ResultCode as ResultCodeData;
                    if (resultCode !== undefined) {
                        this.setResumeData(response);
                        errorMessage += ` - Result Code: ${resultCode.ResultCode} "${resultCode.Description}"`;
                        bootstrapErrorModel.resumeErrorResultCode = resultCode;
                    } else if (response.message) {
                        errorMessage += ` - ${response.message}`;
                    } else {
                        errorMessage += ' - reason unknown';
                    }
                    window.setTimeout(() => {
                        OverlaysEventEmitter.emit('showPopup', 'Error', errorMessage, 'Close');
                    });
                    console.error(errorMessage);
                });
        }
    }

    private static setResumeData(resumeData: IBaseServerResponse): void {
        let currentStake = resumeData.GameSettings.DefaultStake;
        if (resumeData.GameMessage) {
            if (resumeData.GameMessage.GameComplete === false) {
                currentStake = resumeData.GameMessage.Stake;
            } else {
                currentStake = resumeData.PlayerData.PreviousStake;
            }
        }
        inversifyContainer.stake.updateStakes(resumeData.GameSettings, currentStake);
        inversifyContainer.stake.initialStake = currentStake;

        if (demoState.isUnauthenticatedDemo) {
            userModel.setCredentials(resumeData.PlayerData?.UserId ?? 0, 1);
        }

        if (resumeData.DemoSettings) {
            demoState.demoGamesRemaining = resumeData.DemoSettings.RemainingDemoGames;
        }

        if (resumeData.PlayerData) {
            userModel.setData(resumeData.PlayerData, resumeData.RequestType, false, resumeData.SessionStatus);
        }

        if (resumeData.GameSettings) {
            inversifyContainer.gameSettings.setData(resumeData);
            if (resumeData.GameSettings.StakeOptions.length === 0) {
                inversifyContainer.gameServer.emit('ON_INVALID_STAKE');
            }
        }

        if (resumeData.GameMessage) {
            const isInBonus = !resumeData.GameMessage.GameComplete;

            if (isInBonus && gameConfig.engineSkinName !== resumeData.GameMessage.Skin.toLowerCase()) {
                // If a game manages to launch a skin when there is an incomplete bonus in another skin,
                // we should show the relevant error and not apply any GameMessage data
                // delays the message giving time for the game to display first
                window.setTimeout(() => {
                    OverlaysEventEmitter.emit('showToast', '', container.strings.errorBonusInPlay);
                }, 1000);
                return;
            }

            inversifyContainer.gameModel.setData(resumeData);
            inversifyContainer.gameModel.isInProgress = isInBonus;
            // (inversifyContainer.frameConnection as unknown as ShellConnection).methods.updateGameInPlay(inversifyContainer.gameModel.isInProgress);
            inversifyContainer.stake.initialStake = resumeData.GameMessage.Stake;

            if (!resumeData.GameMessage.GameComplete) {
                if (inversifyContainer.gameModel.playMode !== 'FreePlay') {
                    userModel.updateFreePlayBalance(0, resumeData.RequestType);
                }
                endGameValidator.startGame(resumeData);
            }
        }

        sessionDataModel.setData(resumeData); //Relies on data being set in gameModel so must be called after.

        // if another check is needed here we should find a better solution. only italy needs the balance on init changed right now.
        if (queryStringParams.locale === 'it-it' && inversifyContainer.gameModel.isComplete) {
            userModel.hideBalance = true;
        }
        inversifyContainer.gameModel.isNewPlayer = resumeData.ResultCode.ResultCode === RESULT_CODES.NEW_PLAYER;
    }

    private static sendResumeRequest(): Promise<IBaseServerResponse> {
        return inversifyContainer.gameServer.resumeRequest(gameConfig.engineSkinName);
    }

    public static async transitionGameInGame(targetSkin: string = 'bubble'): Promise<void> {
        inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'sub-game-transition', data: { skin: targetSkin } });
    }

    private static async buildStakesString(): Promise<string> {
        const stakes = inversifyContainer.gameSettings.stakeOptions;
        const stakesString = stakes.map(stake => inversifyContainer.currencyFormatter.precise(stake)).join(', ');
        return stakesString;
    }

    private static async localiseDynamicStrings(): Promise<void> {
        const gs = inversifyContainer.gameSettings;
        const RTP = `${Number(gs.rtp).toLocaleString(getLocaleString())}%`;
        const examplePayout = inversifyContainer.currencyFormatter.precise(Number(gs.rtp) * 100);
        const gameStakes = await this.buildStakesString();
        const defaultStake = inversifyContainer.currencyFormatter.precise(gs.defaultStake);
        const stringReplaceOptions = {
            examplePayout,
            RTP,
            gameStakes,
            defaultStake,
        };

        if (inversifyContainer.strings.gameRules) {
            inversifyContainer.strings.gameRules = buildDynamicStringBlock(inversifyContainer.strings.gameRules, stringReplaceOptions);
        }

        if (inversifyContainer.strings.vueHtp) {
            inversifyContainer.strings.vueHtp = buildDynamicStringBlock(inversifyContainer.strings.vueHtp, stringReplaceOptions);
        } else {
            // If there's no vueHtp string defined, we build a placeholder so that any attempts to use it in the game don't error out. 
            // This is for backwards compatibility with older skins that don't have this string, but still want to use the dynamic string features for their how to play.
            const placeholderRecord: Record<string, string> = {
                'Placeholder': 'Record'
            };

            inversifyContainer.strings.vueHtp = buildDynamicStringBlock(placeholderRecord, stringReplaceOptions);
        }

        if (inversifyContainer.strings.howToPlay) {
            inversifyContainer.strings.howToPlay = buildDynamicStringBlock(inversifyContainer.strings.howToPlay, stringReplaceOptions);
        }
    }
}
